const lead = $input.first().json;
const company = (lead.company || '').toLowerCase();

const slug = company
  .replace(/\b(inc|incorporated|ltd|limited|llc|gmbh|oy|ab|as|aps|co|corp|corporation|group|holdings|plc|pty|pvt|s\.?a\.?|s\.?r\.?l\.?|ag|se|nv|bv)\b/gi, '')
  .replace(/[^a-z0-9]/g, '')
  .trim();

const scrapeUrl = lead.scrape_url || (slug ? `https://www.${slug}.com` : null);

return [{
  json: {
    ...lead,
    scrape_url: scrapeUrl,
    company_slug: slug,
    first_name: (lead.contact_name || '').split(' ')[0] || 'there'
  }
}];

const lead = $('Build Scrape URL').first().json;

let homepageContent = '';
let careersContent = '';

try {
  const homeResult = $('Scrape Homepage').first().json;
  homepageContent = homeResult?.data?.markdown || homeResult?.markdown || '';
} catch (e) { homepageContent = ''; }

try {
  const careersResult = $('Scrape Careers Page').first().json;
  careersContent = careersResult?.data?.markdown || careersResult?.markdown || '';
} catch (e) { careersContent = ''; }

homepageContent = homepageContent.substring(0, 3000);
careersContent = careersContent.substring(0, 3000);

return [{
  json: {
    ...lead,
    homepage_markdown: homepageContent,
    careers_markdown: careersContent,
    has_homepage: homepageContent.length > 100,
    has_careers: careersContent.length > 100
  }
}];

const ai = $input.first().json;
const lead = $('Extract Intelligence').first().json;

let message = '';
try {
  message = ai.content?.[0]?.text || ai.text || '';
  message = message.trim().replace(/^["']/g, '').replace(/["']$/g, '').trim();
} catch (e) {
  message = '';
}

if (!message) {
  const name = lead.first_name || 'there';
  const company = lead.company || 'your company';
  message = `Hi ${name} — interesting what ${company} is building. Scaling teams is always the hard part. Would love to connect.`;
}

if (message.length > 300) {
  message = message.substring(0, 297) + '...';
}

return [{
  json: {
    lead_id: lead.id,
    scrape_url: lead.scrape_url,
    homepage_markdown: lead.homepage_markdown,
    careers_markdown: lead.careers_markdown,
    generated_connection_note: message
  }
}];

// Add a new field called 'myNewField' to the JSON of the item
$input.item.json.myNewField = 1;

return $input.item;

const payload = $input.first().json;
const items = payload.body?.leads || payload.leads || [];
return items.map(lead => ({ json: lead }));
